        "rho_b": round(rho_b, 4),
        "mean_diff": round(point_delta, 4),
        "ci_lower": round(ci_lo, 4),
        "ci_upper": round(ci_hi, 4),
        "p_bootstrap": round(p_boot, 6),
        "n_boot": count,
